<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { hotelApi } from '../../api'
import { errorMessage } from '../../api/client'

type Change = Record<string, any>
const items = ref<Change[]>([])
const loading = ref(false)
const eventCount = computed(() => items.value.length)
const affectedCount = computed(() => items.value.reduce((sum, item) => sum + (item.processing_result?.affectedProducts?.length || 0), 0))
function label(value: string) { return ({ PARTNER_RESOURCE: '合作体验', ROOM: '临期客房', HOTEL_SERVICE: '酒店服务' } as Record<string, string>)[value] || value }
function eventLabel(value: string) { return ({ PARTNER_RESOURCE_STATUS_CHANGED: '合作资源状态变化', PARTNER_RESOURCE_CAPACITY_CHANGED: '合作体验名额变化', ROOM_INVENTORY_CHANGED: '临期客房库存变化', HOTEL_SERVICE_QUANTITY_CHANGED: '酒店服务名额变化' } as Record<string, string>)[value] || '资源变化' }
function loadStatus(item: Change) { return item.processing_result?.affectedProducts?.length ? '已同步' : item.processed ? '已处理' : '待处理' }
async function load() { loading.value = true; try { items.value = (await hotelApi.changes()).data } catch (e) { errorMessage(e) } finally { loading.value = false } }
onMounted(load)
</script>

<template>
  <div class="operations-page"><div class="operations-hero"><div><div class="eyebrow">LIVE OPERATIONS · REAL-TIME RECOMPUTATION</div><h1>动态运营中心</h1><p>商户改一个名额，StayScape 会把受影响的产品、库存状态和游客端同步结果放在这里。</p></div><div class="operations-live"><i /> LIVE<br /><small>EVENT STREAM</small></div></div><div class="operations-stats"><div><span>EVENTS</span><strong>{{ eventCount }}</strong><small>最近资源变化</small></div><div><span>AFFECTED PRODUCTS</span><strong>{{ affectedCount }}</strong><small>已触发重算</small></div><div><span>SYNC STATUS</span><strong>H5 SYNCED</strong><small>前台与经营端共享同一状态</small></div></div><div class="operations-toolbar"><span>RECENT RESOURCE EVENTS</span><el-button plain @click="load">刷新事件</el-button></div><div v-if="loading" class="operations-empty">正在读取实时调整事件…</div><div v-else-if="!items.length" class="operations-empty"><span class="operations-empty__mark">↻</span><strong>等待下一次资源变化</strong><p>当商户调整名额、日期或状态，联动结果会出现在这里。</p></div><div v-else class="operations-feed"><div v-for="item in items" :key="item.id" class="operations-event"><div class="event-rail"><span class="event-dot" /><i /></div><div class="event-card"><div class="event-card__head"><div><span class="event-type">{{ eventLabel(item.event_type) }}</span><strong>{{ label(item.resource_type) }} #{{ item.resource_id }}</strong></div><span class="event-time">{{ String(item.created_at).replace('T',' ').slice(0,16) }}</span></div><p class="event-reason">{{ item.reason || '资源状态发生变化，系统开始检查受影响产品。' }}</p><div v-if="item.processing_result?.affectedProducts?.length" class="affected-products"><div v-for="adjustment in item.processing_result.affectedProducts" :key="adjustment.product_id" class="affected-product"><div class="affected-product__main"><span class="affected-product__label">AFFECTED PRODUCT</span><strong>{{ adjustment.product_name }}</strong><small>{{ adjustment.action === 'REPLACE_RESOURCE' ? '已替换资源并重新计算' : '确定性规则已重新计算' }}</small></div><div class="affected-product__numbers"><span>{{ adjustment.old_quantity }} 套</span><b>→</b><strong>{{ adjustment.new_quantity }} 套</strong><el-tag :type="adjustment.status === 'LOW_STOCK' ? 'warning' : adjustment.status === 'PAUSED' ? 'danger' : 'success'" effect="dark">{{ adjustment.status === 'LOW_STOCK' ? '库存紧张' : adjustment.status === 'PAUSED' ? '已暂停' : '已同步' }}</el-tag></div><p>{{ adjustment.reason }}</p></div></div><div class="event-checks"><span>✓ Inventory recalculated</span><span>✓ Product updated</span><span>✓ {{ loadStatus(item) }}</span></div></div></div></div></div>
</template>

