stats{grid-template-columns:1fr;margin-top:28px}.event-card__head{display:block}.event-time{display:block;margin-top:9px}.affected-product__numbers{flex-wrap:wrap}.affected-product__numbers :deep(.el-tag){margin-left:0}}
